result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/slots/src/slots.ts", "content": "// All date math below is done in UTC on purpose: constructing ISO strings and
// reading them back via Date.parse is timezone-independent, so this logic
// behaves identically regardless of the host machine's local timezone.

export interface Interval {
  /** inclusive start, "HH:MM" */
  0: string;
  /** exclusive end, "HH:MM" */
  1: string;
}

/** weekday (0 = Sunday .. 6 = Saturday, matching Date#getUTCDay) -> intervals */
export type OpeningHours = Record<number, Interval[]>;

export interface Booking {
  start: string; // ISO
  end: string; // ISO
}

export interface GenerateOptions {
  /** ISO instant; slots starting before this instant are dropped. */
  now?: string;
  /** slot grid in minutes, default 15 */
  stepMin?: number;
}

const MIN = 60_000;

function parseHM(hm: string): number {
  const [h, m] = hm.split(':').map(Number);
  return h * 60 + m;
}

function midnightUTC(date: string): number {
  // Accept "YYYY-MM-DD"; normalize through UTC to stay tz-safe.
  return Date.parse(`${date}T00:00:00Z`);
}

function toISO(ms: number): string {
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, 'Z');
}

/**
 * Returns every free slot of `durationMin` aligned to the step grid
 * (default 15 minutes), as ISO start strings.
 *
 * - Slots must fit entirely inside one opening interval (no spanning a gap).
 * - A slot overlapping any booking (even just touching its edge) is excluded;
 *   back-to-back bookings leave only exact-fit gaps.
 * - If `now` is given, slots whose start is strictly before `now` are removed,
 *   including slots already in progress at `now`.
 * - If durationMin exceeds every interval of that weekday, the result is empty.
 */
export function generateSlots(
  openingHours: OpeningHours,
  date: string,
  durationMin: number,
  bookings: Booking[],
  options: GenerateOptions = {},
): string[] {
  const step = (options.stepMin ?? 15) * MIN;
  const duration = durationMin * MIN;
  if (duration <= 0) return [];

  const dayStart = midnightUTC(date);
  const weekday = new Date(dayStart).getUTCDay();
  const cutoff = options.now !== undefined ? Date.parse(options.now) : -Infinity;
  const result: string[] = [];

  for (const [fromHm, toHm] of openingHours[weekday] ?? []) {
    const openAt = dayStart + parseHM(fromHm) * MIN;
    const closeAt = dayStart + parseHM(toHm) * MIN;

    // First candidate on/after both the interval start and the cutoff.
    let t = Math.max(openAt, cutoff);
    // Align up to the step grid relative to midnight.
    const over = (t - dayStart) % step;
    if (over !== 0) t += step - over;

    while (t + duration <= closeAt) {
      const end = t + duration;
      const overlapsBooking = bookings.some((b) => {
        const bs = Date.parse(b.start);
        const be = Date.parse(b.end);
        return bs < end && be > t; // half-open [t, end) overlap
      });
      if (!overlapsBooking) {
        result.push(toISO(t));
      }
      t += step;
    }
  }

  return result;
}
"})
