result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/slots/tests/slots.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { generateSlots, type OpeningHours } from '../src/slots.js';

// 2024-06-17 is a Monday (weekday 1).
const MON = '2024-06-17';
const TUE = '2024-06-18';

const hours: OpeningHours = {
  1: [['09:00', '12:30'], ['13:30', '18:00']],
  2: [['10:00', '12:00']],
};

describe('generateSlots', () => {
  it('produces a full aligned grid for an empty day', () => {
    const slots = generateSlots({ 1: [['09:00', '10:30']] }, MON, 45);
    expect(slots).toEqual([
      '2024-06-17T09:00:00Z',
      '2024-06-17T09:45:00Z',
      '2024-06-17T10:15:00Z',
    ]);
    // 90 min interval, 45 min slots, last start must fit before close.
    expect(slots.length).toBe(3);
  });

  it('aligns to 15-minute boundaries when the interval starts off-grid', () => {
    // 09:07 is off-grid; first slot should be 09:15.
    const slots = generateSlots({ 1: [['09:07', '10:00']] }, MON, 30);
    expect(slots).toEqual([
      '2024-06-17T09:15:00Z',
      '2024-06-17T09:30:00Z', // ends exactly at close -> included
    ]);
  });

  it('respects gaps between intervals (no slot spans lunch)', () => {
    const slots = generateSlots(hours, MON, 60);
    expect(slots.every((s) => !s.includes('T12:') || s < '2024-06-17T12:00')).toBe(true);
    expect(slots).toContain('2024-06-17T11:30:00Z'); // ends exactly at 12:30
    expect(slots).toContain('2024-06-17T13:30:00Z'); // afternoon opener
    expect(slots).not.toContain('2024-06-17T12:00:00Z');
    expect(slots).not.toContain('2024-06-17T12:15:00Z');
  });

  it('excludes slots that overlap a booking edge', () => {
    const slots = generateSlots(
      { 1: [['09:00', '12:00']] },
      MON,
      60,
      [{ start: '2024-06-17T10:30:00Z', end: '2024-06-17T11:00:00Z' }],
    );
    // 10:00 slot would run into the booking; 10:30 overlaps it; both removed.
    expect(slots).toEqual([
      '2024-06-17T09:00:00Z',
      '2024-06-17T09:15:00Z',
      '2024-06-17T09:30:00Z',
      '2024-06-17T09:45:00Z',
      '2024-06-17T11:00:00Z',
    ]);
  });

  it('handles back-to-back bookings leaving only exact-fit gaps', () => {
    const slots = generateSlots(
      { 1: [['09:00', '13:00']] },
      MON,
      60,
      [
        { start: '2024-06-17T09:00:00Z', end: '2024-06-17T10:00:00Z' },
        { start: '2024-06-17T10:00:00Z', end: '2024-06-17T11:00:00Z' },
      ],
    );
    expect(slots).toEqual([
      '2024-06-17T11:00:00Z',
      '2024-06-17T11:15:00Z',
      '2024-06-17T11:30:00Z',
      '2024-06-17T11:45:00Z',
      '2024-06-17T12:00:00Z',
    ]);
  });

  it('returns [] on a fully booked day', () => {
    const slots = generateSlots(
      { 1: [['09:00', '12:30']] },
      MON,
      60,
      [
        { start: '2024-06-17T08:00:00Z', end: '2024-06-17T12:31:00Z' },
      ],
    );
    expect(slots).toEqual([]);
  });

  it('returns [] when duration is longer than any interval', () => {
    // Longest interval is 210 min; ask for 240.
    expect(generateSlots(hours, MON, 240)).toEqual([]);
  });

  it('returns [] on a day with no opening hours at all', () => {
    expect(generateSlots(hours, TUE === MON ? TUE : '2024-06-19', 30)).toEqual([]); // Wednesday
  });

  it('picks the correct weekday from the date', () => {
    // Tuesday has only 10:00-12:00.
    expect(generateSlots(hours, TUE, 120)).toEqual(['2024-06-18T10:00:00Z']);
    expect(generateSlots(hours, TUE, 121)).toEqual([]);
  });

  it('drops past slots with the now cutoff (mid-interval)', () => {
    // now = 10:40 is mid-interval and mid-slot: 10:30 slot already started.
    const slots = generateSlots(
      { 1: [['09:00', '12:30']] },
      MON,
      60,
      [],
      { now: '2024-06-17T10:40:00Z' },
    );
    // First candidate 10:40 aligns up to 10:45; 10:45+60 <= 12:30 ok.
    expect(slots).toEqual([
      '2024-06-17T10:45:00Z',
      '2024-06-17T11:00:00Z',
      '2024-06-17T11:15:00Z',
      '2024-06-17T11:30:00Z',
    ]);
  });

  it('cutoff exactly at an interval start keeps everything', () => {
    const slots = generateSlots(
      { 1: [['09:00', '10:00']] },
      MON,
      30,
      [],
      { now: '2024-06-17T09:00:00Z' },
    );
    expect(slots).toEqual([
      '2024-06-17T09:00:00Z',
      '2024-06-17T09:30:00Z',
    ]);
  });

  it('combines cutoff with bookings', () => {
    const slots = generateSlots(
      { 1: [['09:00', '12:00']] },
      MON,
      30,
      [{ start: '2024-06-17T10:00:00Z', end: '2024-06-17T10:30:00Z' }],
      { now: '2024-06-17T09:20:00Z' },
    );
    expect(slots).toEqual([
      '2024-06-17T09:30:00Z',
      '2024-06-17T09:45:00Z',
      '2024-06-17T10:30:00Z',
      '2024-06-17T10:45:00Z',
      '2024-06-17T11:00:00Z',
      '2024-06-17T11:15:00Z',
      '2024-06-17T11:30:00Z',
    ]);
  });
});
"})
